import type { StudyQuestion } from "./study";

/* Scenario-based question banks: 20 per cert (10 medium / 10 hard). */
export const scenarioQuestions1: Record<string, StudyQuestion[]> = {
  "databricks-data-engineer-associate": [
    { q: "A pipeline writes to a Delta table every 5 minutes, and downstream BI users complain of slow reads even though row counts are modest. File listing shows thousands of small files. What should you run to fix read performance without changing the ingestion pattern?", o: ["VACUUM with 0 retention", "OPTIMIZE (optionally with ZORDER BY the most-filtered column)", "DROP and recreate the table", "Switch to CONCATENATE loads"], a: 1, e: "Frequent small-batch writes fragment a Delta table into many small files, which hurts read throughput. OPTIMIZE compacts them into fewer, larger files, and ZORDER BY co-locates data on frequently filtered columns for faster reads — without touching the ingestion job.", t: "Scenario · Medium" },
    { q: "You need a table that can be safely dropped by an analyst without risking accidental loss of the underlying data files, since another team also reads the same files directly from cloud storage. How should the table be created?", o: ["As a MANAGED table", "As an EXTERNAL table with LOCATION pointing to the shared path", "As a VIEW only", "As a temporary view"], a: 1, e: "EXTERNAL tables decouple metadata from data: DROP TABLE removes only the metastore entry, leaving files intact in the specified LOCATION — safe when other consumers read the same files directly.", t: "Scenario · Medium" },
    { q: "New CSV files land in cloud storage continuously from many source systems, and file counts can spike into the millions over time. Which ingestion approach scales best and avoids reprocessing files already loaded?", o: ["A daily full COPY INTO of the entire folder", "Auto Loader with cloudFiles, using file notification mode", "A resident LOAD in Qlik", "Re-running CREATE TABLE AS SELECT nightly"], a: 1, e: "Auto Loader is built for high file-volume, continuously arriving data. Its cloudFiles source tracks ingested files incrementally and idempotently, and file notification mode avoids expensive directory listings at scale — unlike COPY INTO, which is better suited to smaller, known file sets.", t: "Scenario · Medium" },
    { q: "A silver table must reflect only the latest state per customer_id after upstream sends both inserts and updates keyed by customer_id. Which Delta operation is the correct pattern?", o: ["INSERT INTO silver SELECT * FROM bronze", "MERGE INTO silver USING bronze ON silver.customer_id = bronze.customer_id WHEN MATCHED THEN UPDATE ... WHEN NOT MATCHED THEN INSERT", "CONCATENATE bronze and silver", "TRUNCATE silver then INSERT"], a: 1, e: "MERGE INTO is the atomic upsert pattern: matched rows are updated in place, unmatched rows are inserted, giving you the latest state per key in a single transaction — exactly what change-data-style upserts need.", t: "Scenario · Medium" },
    { q: "A data engineer accidentally overwrote a gold table with a bad transformation an hour ago, but VACUUM hasn't run since. What is the fastest recovery path?", o: ["Restore from an external backup system", "SELECT * FROM gold VERSION AS OF <n> (or TIMESTAMP AS OF) and use RESTORE TABLE to that version", "Re-run the entire pipeline from bronze", "There is no way to recover"], a: 1, e: "Because the transaction log still has the prior version (VACUUM hasn't purged it), Delta time travel lets you query or RESTORE TABLE to the version/timestamp before the bad write — much faster than a full pipeline replay.", t: "Scenario · Medium" },
    { q: "A DLT pipeline should permanently discard rows where order_amount is negative, rather than just flagging them. Which expectation clause achieves this?", o: ["CONSTRAINT valid_amount EXPECT (order_amount >= 0)", "CONSTRAINT valid_amount EXPECT (order_amount >= 0) ON VIOLATION DROP ROW", "CONSTRAINT valid_amount EXPECT (order_amount >= 0) ON VIOLATION FAIL UPDATE", "A comment in the SQL"], a: 1, e: "The default EXPECT only tracks/warns and keeps the row. ON VIOLATION DROP ROW removes violating records from the output while still logging metrics, which is exactly what's needed to silently discard bad rows.", t: "Scenario · Hard" },
    { q: "A team wants downstream systems to receive only the row-level changes (inserts/updates/deletes) made to a Delta table each day, not a full table scan. What should they enable and read from?", o: ["Time travel with VERSION AS OF only", "Change Data Feed, enabling delta.enableChangeDataFeed and reading via table_changes() / readChangeFeed", "A nightly full CONCATENATE export", "Auto Loader on the Delta table's own files"], a: 1, e: "Change Data Feed exposes per-row change types (insert, update_preimage, update_postimage, delete) between two versions or timestamps, which is purpose-built for propagating incremental changes downstream without recomputation.", t: "Scenario · Hard" },
    { q: "A production job cluster fails intermittently with out-of-memory errors only on days with unusually large upstream files, and the job has no retry policy. Which combination best hardens this pipeline?", o: ["Increase notebook timeout only", "Configure job task retries with exponential backoff, and separately address skew/size with autoscaling or larger node types", "Switch to an all-purpose cluster", "Disable Auto Loader schema inference"], a: 1, e: "Retries with backoff handle transient failures, but the root cause (data-driven OOM on large days) needs enough headroom via autoscaling/larger instances; retries alone would just re-fail predictably on the same oversized files.", t: "Scenario · Hard" },
    { q: "An analyst has SELECT on a Unity Catalog table but their queries fail with a permissions error, even though the grant clearly exists on the table.", o: ["The grant needs to be re-run twice", "They are missing USE CATALOG on the catalog and/or USE SCHEMA on the schema needed to traverse to the table", "SELECT grants expire after 24 hours", "Unity Catalog does not support SELECT grants"], a: 1, e: "Unity Catalog requires traversal privileges up the namespace: USE CATALOG and USE SCHEMA are needed to even reach an object, in addition to the object-level privilege (SELECT). A missing traversal grant blocks access despite a valid SELECT grant.", t: "Scenario · Hard" },
    { q: "You must load a new batch of files into a table daily, but the same files sometimes get re-delivered by the source system due to retries upstream, and duplicates must never enter the target table. Which loading approach is safest?", o: ["INSERT INTO with no dedup logic", "COPY INTO, which tracks already-loaded files and skips them on re-run", "CONCATENATE every day", "TRUNCATE and reload from scratch each day"], a: 1, e: "COPY INTO is idempotent by file: it keeps track of which source files have already been loaded and automatically skips them on subsequent runs, preventing duplicate ingestion from redelivered files.", t: "Scenario · Hard" },
    { q: "A schema for incoming JSON events occasionally gains new optional fields from the source team without notice, and the pipeline should absorb this automatically rather than fail.", o: ["Hardcode a fixed schema and fail on mismatch", "Use Auto Loader's schema inference/evolution (cloudFiles.schemaEvolutionMode) so new columns are picked up automatically", "Manually update the schema file every time", "Switch to CSV to avoid schema issues"], a: 1, e: "Auto Loader can infer schema and evolve it automatically as new columns appear, tracking schema in a location and restarting the stream as needed — the standard way to absorb upstream schema drift without manual intervention.", t: "Scenario · Medium" },
    { q: "A workspace admin needs multiple related tasks (ingest, transform, aggregate) to run in a defined dependency order, with the aggregate task only running if both upstream tasks succeed.", o: ["Three separate unrelated jobs run on a shared schedule", "A single multi-task Databricks Job with task dependencies (dependsOn) defining the DAG", "Copy all logic into a single monolithic notebook cell", "Use cron only, with no dependency awareness"], a: 1, e: "Databricks Jobs support multi-task workflows where each task can declare dependsOn relationships, forming a DAG so downstream tasks only run after their dependencies succeed — exactly the orchestration needed here.", t: "Scenario · Medium" },
    { q: "A gold table used for a finance dashboard must never expose rows for a region still under an active data-quality investigation, but the underlying data keeps flowing in.", o: ["Manually delete the region's rows in the gold table", "Add a DLT expectation or WHERE-based filter that excludes the flagged region until cleared, applied at the transformation layer", "Stop the whole pipeline", "Ask the BI team to filter it out on the dashboard side only"], a: 1, e: "Enforcing the exclusion in the pipeline/transformation layer (via an expectation or explicit filter) is more reliable and auditable than relying on every downstream consumer to filter correctly, and keeps the gold table itself trustworthy.", t: "Scenario · Medium" },
    { q: "An engineer wants to see exactly how many records a DLT pipeline dropped due to a data-quality expectation over the last 24 hours.", o: ["This information isn't tracked", "Query the DLT pipeline's event log, which records expectation metrics (passed/failed/dropped record counts) per run", "Manually count rows before and after", "Check the cluster's stdout logs"], a: 1, e: "DLT automatically records pipeline event logs including per-expectation metrics — how many records passed, failed, or were dropped — which can be queried directly for monitoring and auditing data quality over time.", t: "Scenario · Medium" },
    { q: "A data engineer must grant a service principal permission to read and write to a specific schema in Unity Catalog, but not to other schemas in the same catalog.", o: ["GRANT ALL PRIVILEGES ON CATALOG", "GRANT USE CATALOG on the catalog, plus USE SCHEMA, SELECT and MODIFY specifically on that one schema", "Add the service principal as a metastore admin", "There is no schema-level granularity in Unity Catalog"], a: 1, e: "Unity Catalog supports fine-grained, schema-level grants: USE CATALOG for traversal plus USE SCHEMA/SELECT/MODIFY scoped to just the target schema gives the service principal exactly the access needed, leaving sibling schemas untouched.", t: "Scenario · Hard" },
    { q: "A batch job reading from a JDBC source is slow because it pulls all rows through a single connection/partition. How should this be tuned in Spark?", o: ["Increase the JDBC driver's timeout only", "Use partitionColumn, lowerBound, upperBound, and numPartitions on the JDBC read to parallelize the extraction across multiple connections", "Switch to reading via Auto Loader instead", "Cache the JDBC table before reading"], a: 1, e: "Spark's JDBC reader can parallelize by splitting the read into ranges of a numeric partitionColumn across numPartitions connections, avoiding the single-connection bottleneck that a naive JDBC read incurs.", t: "Scenario · Hard" },
    { q: "You must ensure that a Delta table's transaction log doesn't grow unbounded in size over years of operation while still keeping enough history for time travel within a 30-day compliance window.", o: ["Never run VACUUM", "Set an appropriate VACUUM retention (e.g., matching the 30-day requirement) and run it periodically to clean up unreferenced files beyond that window", "Delete the _delta_log folder manually", "Disable the transaction log entirely"], a: 1, e: "VACUUM removes data files no longer referenced by the log beyond the retention threshold; setting retention to match the compliance window (e.g., 30 days) and running it on a schedule keeps storage bounded while preserving the required time-travel window.", t: "Scenario · Hard" },
    { q: "A pipeline reading a large upstream table performs a full table scan every run even though only a date-partitioned subset changed. What table design choice would allow Spark to skip irrelevant files?", o: ["No partitioning; rely on ZORDER alone", "Partition the table by the date column used in WHERE filters, so partition pruning skips files outside the requested range", "Increase cluster size", "Use CONCATENATE loads instead of MERGE"], a: 1, e: "Partitioning by the column commonly filtered on (e.g., date) enables partition pruning: Spark can skip entire partitions/files that don't match the filter, avoiding a full scan for date-scoped queries.", t: "Scenario · Hard" },
    { q: "A Databricks SQL alert should notify the on-call channel only when a KPI query's result crosses a threshold, not on every scheduled refresh.", o: ["Manually check the dashboard every hour", "Configure a Databricks SQL Alert with a condition/threshold on the query result, which triggers notifications only when the condition is met", "Re-run the query and eyeball it", "Use a Job with no condition logic"], a: 1, e: "Databricks SQL Alerts are built exactly for this: they evaluate a query result against a defined condition/threshold on a schedule and only fire notifications when that condition is met, avoiding noisy per-refresh alerts.", t: "Scenario · Hard" },
    { q: "A workspace admin must ensure a service principal running scheduled jobs has exactly the Unity Catalog privileges needed for its target schema and nothing more, following least-privilege practice.", o: ["Grant the service principal metastore admin rights for simplicity", "Grant only USE CATALOG, USE SCHEMA, and the specific object-level privileges (e.g., SELECT, MODIFY) it needs on that schema/table, avoiding broad or admin-level grants", "Reuse a human user's personal access token instead", "Give ALL PRIVILEGES on the catalog"], a: 1, e: "Least-privilege access for a service principal means granting only the traversal and object-level privileges it actually needs for its job's target objects, not broad catalog-wide or admin privileges — a core governance practice for the Associate exam.", t: "Scenario · Medium" },
  ],
  "databricks-data-engineer-professional": [
    { q: "A streaming aggregation job needs to tolerate late-arriving events up to 30 minutes late while still bounding state size for a windowed count. What should be configured?", o: ["A larger cluster only", "withWatermark on the event-time column with a 30-minute threshold, combined with a window aggregation", "checkpointLocation alone", "A static join instead of streaming"], a: 1, e: "Watermarking tells Structured Streaming how late data can arrive before state for a window is finalized and dropped, bounding state size while still accepting the specified lateness — exactly the tradeoff described.", t: "Scenario · Medium" },
    { q: "A team wants to track full history of dimension changes (e.g., a customer's address over time) so historical fact rows still join to the address that was valid at that time. Which pattern applies?", o: ["SCD Type 1", "SCD Type 2, adding effective/expiry dates or a current-flag with new rows per change", "TRUNCATE and reload the dimension", "A single mutable row per customer"], a: 1, e: "SCD Type 2 preserves history by inserting a new versioned row per change (with effective/expiry dates or a current flag), which is what's required to correctly join historical facts to the dimension value that was valid at that time.", t: "Scenario · Medium" },
    { q: "A nightly Delta MERGE into a large fact table is taking increasingly long as the table grows, even though only a small fraction of rows change each night. What is the most effective tuning lever?", o: ["Switch to CONCATENATE", "Partition/ZORDER the table on the MERGE join keys and ensure the source is filtered to only the affected partitions", "Disable the transaction log", "Run VACUUM more frequently"], a: 1, e: "MERGE performance depends heavily on how efficiently matching rows can be located. Partitioning/ZORDERing on the join key, and dynamic file pruning by filtering the source to relevant partitions, drastically reduces the files that must be scanned and rewritten.", t: "Scenario · Medium" },
    { q: "You need to join a continuously updating stream of clickstream events with a slowly changing but non-streaming dimension table (loaded once) without re-reading the whole dimension per micro-batch.", o: ["Convert the dimension to a stream as well", "A stream-static join, where the streaming DataFrame is joined with a static (batch) DataFrame", "Use CONCATENATE inside foreachBatch", "This is not possible in Structured Streaming"], a: 1, e: "Stream-static joins are the standard pattern for enriching a stream with a batch/dimension table; Spark re-reads the static side each micro-batch based on its current snapshot, which is efficient for slowly changing reference data.", t: "Scenario · Medium" },
    { q: "A junior engineer wants to give a BI team read access to only the non-PII columns of a Unity Catalog table, keeping the base table's raw PII columns restricted.", o: ["Grant SELECT on the whole table and trust the BI team", "Create a dynamic view (or a column-masked view) exposing only the allowed columns, and grant SELECT on the view instead", "Duplicate the table without PII columns manually every day", "Use Section Access"], a: 1, e: "A view (optionally with dynamic column masking based on group membership) is the standard way to expose a restricted projection of a table; granting SELECT on the view rather than the base table enforces the column-level restriction.", t: "Scenario · Hard" },
    { q: "During a Professional-level performance review, the Spark UI shows one task in a stage taking 20x longer than its peers on a join. What does this most likely indicate, and what is a fix?", o: ["Insufficient driver memory; add more driver cores", "Data skew on the join key; consider salting the key or broadcasting the smaller side", "The cluster needs a restart", "The job should use RDDs instead of DataFrames"], a: 1, e: "A single straggler task strongly suggests data skew — one partition holding disproportionately more data (e.g., a hot key). Salting the skewed key or broadcasting the smaller table are standard mitigations.", t: "Scenario · Hard" },
    { q: "A CI/CD pipeline for Databricks jobs must promote the same job definition and notebooks from dev to staging to prod with environment-specific parameters (catalogs, schemas). What is the recommended approach?", o: ["Manually copy notebooks between workspaces", "Databricks Asset Bundles (DABs) with environment-specific target configurations", "Hardcode catalog names in every notebook", "Use dbutils.notebook.run for every deployment"], a: 1, e: "Databricks Asset Bundles are the standard infrastructure-as-code mechanism for defining jobs/pipelines as YAML and deploying them consistently across dev/staging/prod targets, with per-target overrides for things like catalog/schema.", t: "Scenario · Hard" },
    { q: "A pipeline must guarantee exactly-once semantics when writing streaming aggregates to a Delta sink, even if the job restarts mid-batch after a driver failure.", o: ["This cannot be guaranteed by Structured Streaming", "Use a reliable checkpointLocation on the stream, which stores offsets and enables exactly-once, idempotent writes to Delta on restart", "Disable watermarking", "Switch to append-only writes with no checkpoint"], a: 1, e: "Structured Streaming's checkpointing (write-ahead log of offsets and state) combined with Delta's transactional writes provides exactly-once processing guarantees across restarts, as long as the checkpoint location is durable and consistent.", t: "Scenario · Hard" },
    { q: "You need unit tests for a PySpark transformation function that doesn't depend on a live cluster and runs quickly in CI. What is the standard testing approach?", o: ["Only test manually in a notebook", "Use a local SparkSession in a test framework (e.g., pytest) with small in-memory DataFrames to assert transformation logic", "Run the full production pipeline nightly and check output", "Skip testing Spark code entirely"], a: 1, e: "Professional-level testing practice uses a local SparkSession with small fixture DataFrames inside a standard test framework, enabling fast, deterministic unit tests of transformation logic in CI without needing a live cluster.", t: "Scenario · Hard" },
    { q: "Two teams both need MERGE-based upserts into the same Delta table concurrently, and you're seeing ConcurrentAppendException errors. What best explains and addresses this?", o: ["Delta doesn't support concurrent writes at all", "Concurrent writers touched overlapping files/partitions; reduce conflict by partitioning appropriately and retrying transactions, or serialize conflicting writers", "Switch to Parquet to avoid the transaction log", "Use VACUUM to fix concurrency"], a: 1, e: "Delta uses optimistic concurrency control: conflicting concurrent writes to overlapping files can throw exceptions like ConcurrentAppendException. Reducing overlap (e.g., via partitioning aligned to writers) and implementing retry logic are the recommended mitigations.", t: "Scenario · Hard" },
    { q: "A downstream consumer needs to know precisely which rows changed in a Delta table between two job runs (not just the final state) to drive an incremental aggregation, and re-scanning the full table nightly is too expensive.", o: ["Read the whole table each night and diff manually", "Enable Change Data Feed and read only the changes via table_changes(table, startVersion, endVersion)", "Use time travel to compare two full snapshots row by row", "This requires a third-party CDC tool"], a: 1, e: "Change Data Feed gives row-level change records (with change type) between versions directly, which is far cheaper than diffing two full snapshots and is the native Delta mechanism for this use case.", t: "Scenario · Hard" },
    { q: "A streaming job with a 10-minute watermark occasionally drops legitimate late events that arrive 15 minutes late during a known upstream outage window. What is the tradeoff being made, and how would you address it?", o: ["Watermarks never drop data; something else is wrong", "Widening the watermark threshold accepts more lateness at the cost of larger state and higher latency for finalizing results; the team must balance this against the outage pattern", "Remove the watermark entirely with no downside", "Switch to batch processing permanently"], a: 1, e: "A watermark is an explicit tradeoff: events later than the threshold are dropped by design to bound state size and finalize windows. Widening it (e.g., to 20 minutes) would capture the outage's late data but increases state size and end-to-end latency — a conscious tuning decision, not a bug.", t: "Scenario · Hard" },
    { q: "A Professional-level pipeline must expose row-level security so that regional managers only see their own region's rows in a shared Unity Catalog table, without maintaining separate tables per region.", o: ["Create a full physical copy of the table per region", "Use a dynamic view with row filters based on is_account_group_member() or current_user() compared to a region-mapping table", "Grant SELECT on the whole table to everyone", "Rely on the BI tool to filter, with no enforcement in the table layer"], a: 1, e: "Unity Catalog supports row-level security via dynamic views that filter rows using functions like is_account_group_member() or current_user() against a mapping table — enforced centrally at the data layer rather than duplicated per region or left to the BI tool.", t: "Scenario · Hard" },
    { q: "A batch job that writes to a Delta table via foreachBatch inside a streaming query needs to also update a separate audit table transactionally with the same batch. What pattern supports this?", o: ["Two independent, unrelated streaming queries", "Within foreachBatch, perform both writes (main table MERGE and audit insert) against the same micro-batch DataFrame, optionally wrapping related operations so both reflect the same batch consistently", "Write the audit table once a week separately", "This cannot be done in Structured Streaming"], a: 1, e: "foreachBatch exposes the micro-batch as a static DataFrame, letting you perform multiple operations (e.g., a MERGE into the main table and an insert into an audit table) against that same batch, keeping both writes aligned to the same data.", t: "Scenario · Hard" },
    { q: "A team's DLT pipeline in 'triggered' mode is meant to run on a schedule and stop, but they need to migrate a subset of tables to near-real-time freshness without duplicating pipeline logic.", o: ["Rewrite the entire pipeline as a separate streaming job", "Change the relevant tables to STREAMING LIVE TABLE sources within the same pipeline and switch that pipeline (or the affected flow) to continuous mode as needed", "This isn't configurable per table", "Only Python DLT pipelines support streaming"], a: 1, e: "DLT lets individual tables be declared as streaming (STREAMING LIVE TABLE / streaming table) within the same pipeline definition, and pipeline execution mode (triggered vs continuous) can be adjusted — avoiding a full logic rewrite to change freshness characteristics.", t: "Scenario · Hard" },
    { q: "An engineer needs to validate, before merging a pull request, that a refactored transformation still produces the same output as the previous version on a representative sample, as part of CI.", o: ["Manually eyeball a spreadsheet export", "Write an automated test that runs both versions against fixture data and asserts DataFrame equality (schema and rows) as part of the CI pipeline", "Skip validation since Spark code is hard to test", "Deploy directly to production and monitor for issues"], a: 1, e: "Automated regression tests comparing old vs. new transformation output on fixture data, run in CI before merge, is the standard practice for safely refactoring Spark pipelines at the Professional level.", t: "Scenario · Hard" },
    { q: "A job needs to write to two different catalogs in Unity Catalog within the same notebook run — one for a curated gold table and one for an audit log — using the same cluster.", o: ["Not possible; one cluster can only see one catalog", "Fully qualify each write with its own catalog.schema.table reference (or USE CATALOG/USE SCHEMA before each block), since Unity Catalog supports cross-catalog access from a single cluster", "Requires two separate clusters", "Requires disabling Unity Catalog"], a: 1, e: "Unity Catalog's three-level namespace allows a single cluster/session to read and write across multiple catalogs by fully qualifying references (catalog.schema.table) or switching context with USE CATALOG/USE SCHEMA, without needing separate clusters.", t: "Scenario · Hard" },
    { q: "A pipeline occasionally fails because an upstream schema change (a column type change from int to string) breaks downstream MERGE logic silently producing nulls instead of erroring. How should the team guard against this going forward?", o: ["Ignore it since Delta handles all schema changes automatically", "Enable schema enforcement (and only allow schema evolution explicitly via mergeSchema where intended) so unexpected type changes raise an error instead of silently coercing", "Turn off all schema checks for speed", "Rewrite the table as Parquet"], a: 1, e: "Delta's default schema enforcement rejects writes that don't match the expected schema, catching unexpected type changes early; explicit schema evolution (mergeSchema) should be reserved for intentional, reviewed changes rather than left wide open.", t: "Scenario · Hard" },
    { q: "A Professional exam scenario describes a pipeline where Bronze receives raw JSON, Silver deduplicates and enforces types, and Gold aggregates for reporting — but Gold occasionally shows stale numbers relative to Silver. What is the most likely operational gap?", o: ["Gold aggregations are inherently always stale", "The Gold refresh job/task isn't triggered or scheduled to run after Silver completes (missing job dependency or trigger), so it processes an older Silver snapshot", "Bronze should aggregate instead of Gold", "Delta tables can't be aggregated"], a: 1, e: "In a medallion pipeline, staleness downstream typically points to an orchestration gap — Gold not being triggered immediately after (or dependent on) Silver's completion — rather than a fundamental limitation, so fixing job dependencies/triggers resolves it.", t: "Scenario · Hard" },
    { q: "A team must migrate a large Delta table's storage layout so queries filtering on two different columns (region and date) both benefit from data skipping, since ZORDER effectively supports only a small number of prioritized columns.", o: ["ZORDER on unlimited columns with equal priority", "Partition by the coarser, commonly-filtered column (e.g., date) and ZORDER by the finer column (e.g., region) within partitions, since ZORDER effectiveness degrades with too many columns", "Only ever use ZORDER, never partitioning", "Store two full physical copies of the table, one sorted per column"], a: 1, e: "Best practice combines coarse-grained partitioning (e.g., by date) with ZORDER on a small number of additional high-cardinality filter columns (e.g., region) within each partition — ZORDER's effectiveness drops sharply beyond a handful of columns, so this layered approach maximizes data skipping for both filters.", t: "Scenario · Hard" },
  ],
  "databricks-apache-spark-developer": [
    { q: "A wide transformation like groupBy().agg() is running slowly on a large dataset, and the Spark UI shows a large shuffle. What is the most direct lever to reduce shuffle cost for a downstream join on the same key?", o: ["Increase driver memory only", "Repartition the data on the join/group key before the operation so related rows co-locate, reducing shuffle in subsequent stages", "Switch to coalesce(1)", "Cache the raw input only"], a: 1, e: "Repartitioning on the key used for grouping/joining ensures related rows land in the same partition, which reduces the amount of data reshuffled across the cluster for that and subsequent operations on the same key.", t: "Scenario · Medium" },
    { q: "You need to reduce the number of output files after a large job without triggering a full shuffle, since the data is already reasonably balanced.", o: ["repartition(n)", "coalesce(n), since it can reduce partitions without a full shuffle", "groupByKey()", "cache() followed by count()"], a: 1, e: "coalesce() reduces partition count by merging existing partitions locally where possible, avoiding a full shuffle — appropriate when you're decreasing partitions and the data is already fairly balanced. repartition() always triggers a full shuffle.", t: "Scenario · Medium" },
    { q: "A join between a 500 GB fact table and a 10 MB lookup table is running unexpectedly slowly with a full shuffle join plan. What should you check or force?", o: ["Increase the number of shuffle partitions only", "Ensure a broadcast join is used for the small table (e.g., via broadcast() hint) instead of a shuffle (sort-merge) join", "Cache both tables fully", "Switch both tables to RDDs"], a: 1, e: "For a large table joined with a much smaller one, a broadcast join (sending the small table to every executor) avoids shuffling the large table entirely. If Spark isn't auto-broadcasting (e.g., size threshold or stats missing), an explicit broadcast() hint fixes it.", t: "Scenario · Medium" },
    { q: "A DataFrame transformation chain is defined but nothing appears to execute in the Spark UI until a later .count() call. Why?", o: ["Spark has crashed silently", "Transformations are lazy; only an action (like count, collect, write) triggers execution of the DAG", "The code has a syntax error", "DataFrames execute eagerly by default"], a: 1, e: "Spark builds a logical/physical plan lazily as transformations are chained, and only executes (materializing the DAG into stages/tasks) when an action such as count(), collect(), or write() is called.", t: "Scenario · Medium" },
    { q: "You need to apply a custom Python function row-by-row over a large DataFrame with better performance than a plain UDF, leveraging vectorization.", o: ["A standard (row-at-a-time) UDF", "A Pandas UDF (vectorized UDF), which batches rows into pandas Series/DataFrames using Arrow", "collect() then a Python loop", "Convert to an RDD and use map()"], a: 1, e: "Pandas UDFs use Apache Arrow to transfer data in batches and operate on pandas Series/DataFrames, which is substantially faster than row-at-a-time Python UDFs due to vectorization and reduced serialization overhead.", t: "Scenario · Medium" },
    { q: "A job caches a large DataFrame with .cache() but later stages still seem to recompute it from scratch after several actions. What is the most likely cause?", o: ["cache() never works in Spark", "The DataFrame was transformed again (creating a new logical plan) after caching, so the new plan isn't the cached one, or the cache was evicted due to memory pressure", "count() disables caching", "Only RDDs can be cached, not DataFrames"], a: 1, e: "cache() marks a specific DataFrame lineage for storage; if you apply further transformations to create a new DataFrame, that new lineage isn't automatically the cached one. Memory pressure can also silently evict cached partitions (recomputed from lineage when needed).", t: "Scenario · Hard" },
    { q: "You're debugging a stage where most tasks finish in seconds but a few take minutes, and the input key distribution shows one key with a disproportionate row count. What Spark-native technique addresses this join skew?", o: ["Increase spark.sql.shuffle.partitions only", "Salt the skewed key (append a random suffix on both sides and adjust the join condition) to spread the hot key across more partitions", "Reduce executor count", "Switch join type to a full outer join"], a: 1, e: "Salting distributes the rows of a hot key across multiple synthetic sub-keys on both sides of the join, spreading what was one overloaded partition/task across many, which directly addresses skew that simple repartitioning by the original key cannot fix.", t: "Scenario · Hard" },
    { q: "A production job intermittently fails with 'Kryo serialization failed' or excessive GC pauses when using custom Scala/Java objects inside RDD transformations at scale. What is a recommended mitigation?", o: ["Ignore it; it self-resolves", "Register custom classes with the Kryo serializer (or minimize custom object use, preferring DataFrame/Dataset APIs with built-in encoders) to reduce serialization overhead", "Switch to Java serialization for everything", "Use collect() to avoid serialization"], a: 1, e: "Kryo is faster and more compact than Java serialization but performs best when custom classes are registered; excessive GC/serialization failures with custom objects are commonly mitigated by registering classes with Kryo or, better, using the DataFrame/Dataset API which has efficient built-in encoding.", t: "Scenario · Hard" },
    { q: "An Adaptive Query Execution (AQE)-enabled job automatically converts what would have been a sort-merge join into a broadcast join partway through execution. What made this possible?", o: ["AQE cannot change join strategy at runtime", "AQE re-optimizes the physical plan using runtime statistics (actual shuffle output sizes), allowing it to switch to a broadcast join if a side turns out to be small enough", "The developer manually forced it", "It only applies to streaming queries"], a: 1, e: "Adaptive Query Execution re-evaluates the query plan at shuffle boundaries using real runtime statistics rather than only static estimates, letting it dynamically switch join strategies (e.g., to broadcast) or coalesce shuffle partitions when actual data sizes justify it.", t: "Scenario · Hard" },
    { q: "A wide transformation produces far more shuffle partitions than needed for the resulting data volume, leaving many tiny tasks with high scheduling overhead. Which AQE feature directly addresses this?", o: ["Dynamic partition pruning", "Coalescing shuffle partitions (spark.sql.adaptive.coalescePartitions.enabled)", "Broadcast join hints", "Kryo serialization"], a: 1, e: "AQE's partition coalescing merges small adjacent shuffle partitions post-shuffle based on actual output sizes, reducing the number of tiny tasks and their associated scheduling overhead without requiring a manual repartition() tune.", t: "Scenario · Hard" },
    { q: "A query filters a partitioned Delta table on a derived expression, e.g. WHERE year(order_date) = 2025, but the physical plan shows a full scan instead of partition pruning on order_date's partition column.", o: ["Partition pruning always works regardless of the filter form", "Wrapping the partition column in a function (year()) prevents static partition pruning; filtering directly on the literal partition column/range instead restores pruning", "This is a bug that cannot be fixed", "Only ZORDER columns can be pruned"], a: 1, e: "Static partition pruning generally requires the filter to reference the partition column directly (or a range on it); wrapping it in a function like year() obscures the relationship from the optimizer, causing a full scan. Filtering on the actual partition values restores pruning.", t: "Scenario · Hard" },
    { q: "You need to deduplicate a DataFrame on (id, event_time) while keeping only the most recent event_time per id, efficiently, without collecting to the driver.", o: ["collect() to the driver and dedupe in Python", "Use a window function (row_number() over a window partitioned by id, ordered by event_time desc) and filter row_number = 1", "dropDuplicates() on id alone", "sort() the whole DataFrame and take the first row overall"], a: 1, e: "A window function partitioned by id and ordered by event_time descending, filtering to row_number()=1, correctly keeps only the latest row per id and scales across the cluster — dropDuplicates(['id']) alone doesn't guarantee which duplicate is kept.", t: "Scenario · Medium" },
    { q: "A developer wants to inspect the physical plan Spark will actually execute for a DataFrame query, including whether a broadcast join was chosen, before running it at scale.", o: ["print(df)", "df.explain(True) (or explain('formatted')) to view the logical and physical plans", "df.show()", "df.count()"], a: 1, e: "explain() (especially with extended/formatted mode) reveals the logical and physical query plans, including join strategies chosen (e.g., BroadcastHashJoin vs SortMergeJoin), letting a developer verify optimizer decisions before running the job at scale.", t: "Scenario · Medium" },
    { q: "A DataFrame with a deeply nested JSON column needs specific nested fields extracted into top-level columns for easier downstream SQL access.", o: ["Manually re-write the JSON in Python", "Use dot notation or getField/getItem on the struct/array columns (e.g., col('data.customer.id')), with explode() for arrays, to flatten nested fields", "Convert to CSV first", "This requires an external ETL tool"], a: 1, e: "Spark SQL functions support direct access into structs via dot notation and into arrays via explode(), which is the standard way to flatten nested JSON columns into top-level, queryable columns.", t: "Scenario · Medium" },
    { q: "A developer needs to run the exact same transformation logic in both a notebook (for exploration) and a packaged Python wheel (for a scheduled job), avoiding duplicated code.", o: ["Copy-paste the code into both places and maintain two copies", "Factor the transformation logic into a shared Python module/package imported by both the notebook and the packaged job, keeping a single source of truth", "Only ever use notebooks, never packaged jobs", "Rewrite the logic in Scala for the job and Python for the notebook"], a: 1, e: "Extracting shared logic into an importable module (installed as a library or included in a wheel) lets both the interactive notebook and the scheduled job call the same code path, avoiding drift between duplicated copies.", t: "Scenario · Medium" },
    { q: "A job reading Parquet files applies a filter on a column that is not sorted or indexed in the files, and Spark still reads full row groups unnecessarily.", o: ["Parquet always supports arbitrary predicate pushdown with no caveats", "Rely on Parquet's built-in min/max statistics per row group for predicate pushdown where applicable, and consider Z-ordering/sorting data on frequently filtered columns (in Delta) to make pushdown more effective", "Switch to uncompressed CSV for faster filtering", "Disable predicate pushdown entirely"], a: 1, e: "Predicate pushdown leverages per-row-group statistics (min/max) to skip irrelevant row groups, but it's most effective when data is physically clustered on the filtered column (e.g., via Z-ordering in Delta); unsorted data limits how much pushdown can skip.", t: "Scenario · Medium" },
    { q: "A job's shuffle stage is spilling large amounts of data to disk, and increasing memory isn't a viable short-term option. Which configuration is most directly related to reducing shuffle spill in this scenario?", o: ["spark.sql.shuffle.partitions tuned to better match data volume (avoiding partitions that are too large per task)", "spark.driver.cores", "spark.sql.autoBroadcastJoinThreshold set to 0", "spark.sql.parquet.compression.codec"], a: 0, e: "Excessive spill often results from too few shuffle partitions relative to data size, making each partition too large to fit in executor memory. Increasing spark.sql.shuffle.partitions so each partition is smaller reduces per-task memory pressure and spill.", t: "Scenario · Hard" },
    { q: "A developer notices that repeated actions on the same expensive DataFrame transformation each re-read the source files from cloud storage, because nothing has told Spark to keep the result around.", o: ["This indicates a bug in Spark's optimizer", "Without caching, every action re-executes the lazy plan from source for that DataFrame's lineage; adding .cache()/.persist() after the expensive read/transform avoids repeated source reads across multiple actions", "Actions never re-read source data", "Only writing to disk avoids repeated reads"], a: 1, e: "Each action re-triggers Spark's lazy execution from the original source for that DataFrame's lineage unless it's explicitly cached. Caching a DataFrame reused across multiple actions avoids redundant re-reads and recomputation.", t: "Scenario · Medium" },
    { q: "A job needs to atomically overwrite only the partitions affected by today's data (e.g., a single day) in a Delta table, leaving all other historical partitions untouched.", o: ["Overwrite the entire table with mode('overwrite') and no partition filter", "Use dynamic partition overwrite (or an explicit replaceWhere condition) so only the partitions present in the write are replaced, leaving others intact", "Manually DELETE the whole table first", "Append duplicate rows and dedupe later"], a: 1, e: "Dynamic partition overwrite (or replaceWhere) replaces only the partitions actually present in the incoming data, safely leaving unrelated historical partitions untouched — unlike a full-table overwrite which would destroy all history.", t: "Scenario · Medium" },
    { q: "A team needs to confirm, from the Spark UI, whether a slow job is bottlenecked on CPU-bound computation versus waiting on shuffle I/O across the network.", o: ["The Spark UI provides no such detail", "Examine the stage/task breakdown (shuffle read/write time vs. compute time, and the Executors tab) to distinguish compute-bound from shuffle/I/O-bound stages", "Only external APM tools can determine this", "Restart the cluster and see if it's faster"], a: 1, e: "The Spark UI's stage and task-level metrics break down time spent in shuffle read/write versus actual task compute time, letting an engineer diagnose whether a bottleneck is CPU-bound computation or shuffle/network I/O.", t: "Scenario · Hard" },
  ],
  "databricks-data-analyst-associate": [
    { q: "A business user asks for a dashboard that automatically re-runs its underlying query every morning at 6am before the team arrives. What Databricks SQL feature should be configured?", o: ["Manually running the query each morning", "A scheduled refresh on the query (and/or dashboard), setting a 6am cron-like schedule", "A one-time alert", "Auto Loader"], a: 1, e: "Databricks SQL queries and dashboards support scheduled refreshes, letting you define a recurring schedule (e.g., daily at 6am) so results are pre-computed and ready before users arrive, without manual intervention.", t: "Scenario · Medium" },
    { q: "An analyst wants a visualization that shows the trend of daily revenue over the last 90 days, highlighting the overall direction rather than exact daily values.", o: ["A pie chart", "A line chart with date on the x-axis and revenue on the y-axis", "A single-value counter", "A table with 90 rows"], a: 1, e: "A line chart is the standard choice for showing a trend over a continuous time axis; it makes the overall direction (up/down/flat) immediately visible in a way a table or single value cannot.", t: "Scenario · Medium" },
    { q: "A dashboard is reused by multiple regional teams who each only need to see their own region's numbers, without duplicating the dashboard.", o: ["Build a separate dashboard per region", "Use a dashboard-level filter/parameter for region that each viewer can set, backed by a parameterized query", "Hardcode the region in the SQL", "Ask each team to manually edit the SQL"], a: 1, e: "Databricks SQL dashboards support parameters/filters that let a single dashboard definition be reused across audiences, with each viewer selecting their own filter value (e.g., region) rather than maintaining duplicate dashboards.", t: "Scenario · Medium" },
    { q: "A SQL warehouse used for BI dashboards is slow to respond to the first query of the day but fast afterward. What Databricks SQL warehouse setting most directly addresses this?", o: ["Increase the query timeout", "Configure auto-stop with a longer idle period, or keep a minimum number of clusters running, to avoid cold-start on the first query", "Switch to a serverless notebook", "Disable caching"], a: 1, e: "The 'cold start' delay happens when the SQL warehouse has scaled down/stopped due to inactivity. Tuning auto-stop (longer idle timeout) or setting a minimum cluster count keeps a warehouse warm, avoiding the startup delay for the first query.", t: "Scenario · Medium" },
    { q: "An analyst needs to combine two result sets with the same columns (current year and prior year sales) into a single result set for a year-over-year visualization.", o: ["JOIN the two queries", "UNION ALL the two queries, tagging each with a year column", "PIVOT the data", "Use two separate charts only"], a: 1, e: "UNION ALL (or UNION) stacks rows from two compatible result sets; adding a year/label column to each side before unioning lets a single chart plot both years together for year-over-year comparison.", t: "Scenario · Medium" },
    { q: "A query result shows unexpectedly high totals after joining an orders table to a returns table, because some orders have multiple return records. What analysis mistake is occurring and how should it be fixed?", o: ["The join itself is broken and Databricks SQL should be restarted", "A fan-out join: each order is being multiplied by its matching returns rows before aggregation; pre-aggregate the returns table (e.g., SUM per order_id) before joining, or aggregate after joining with care using DISTINCT/window logic", "Switching to a pie chart fixes it", "Use SELECT * to avoid the issue"], a: 1, e: "Joining a one-to-many relationship without pre-aggregating causes each 'one' side row to be duplicated per matching row on the 'many' side, inflating SUM/COUNT aggregates. Pre-aggregating the many side (or careful post-join deduplication) resolves the fan-out.", t: "Scenario · Hard" },
    { q: "Leadership wants an alert the moment daily active users drops more than 15% versus the same day last week, sent to Slack/email automatically.", o: ["A manually checked dashboard", "A Databricks SQL Alert with a condition comparing this week's value to last week's (e.g., via a query computing % change), configured with a notification destination", "A one-time query run by hand each day", "This requires a separate BI tool"], a: 1, e: "Databricks SQL Alerts evaluate a scheduled query's result against a threshold condition and can be wired to notification destinations (email, Slack, etc.), which is exactly the automated, condition-based notification described.", t: "Scenario · Hard" },
    { q: "An analyst's dashboard query references a table that a data engineer just renamed as part of a migration, breaking the dashboard silently until someone notices stale/error results.", o: ["Nothing can prevent this", "Establish a change-management practice (e.g., views/aliases for stable external-facing names, or communication before renames) so BI consumers aren't broken by backend renames", "Rebuild the dashboard from scratch each time", "Disable the dashboard permanently"], a: 1, e: "A common best practice is to expose stable, analyst-facing names via views (or coordinate schema changes with consumers) so that backend table renames/refactors don't silently break downstream BI assets — a key analyst-engineer collaboration point covered on this exam.", t: "Scenario · Hard" },
    { q: "A dashboard should visually flag any region where profit margin falls below a target threshold, without requiring the viewer to read every number.", o: ["Add a text note below the chart", "Use conditional formatting / color thresholds on the visualization (e.g., red below target, green above) so outliers are visually obvious", "Sort the table alphabetically", "Remove the metric entirely"], a: 1, e: "Conditional formatting (color-coding values against a threshold) is the standard way to make outliers immediately visible at a glance, which is more effective for fast decision-making than requiring the viewer to scan every row.", t: "Scenario · Hard" },
    { q: "An analyst wants to let dashboard viewers dynamically choose which metric (revenue, units, margin) to visualize in the same chart, without building three separate dashboards.", o: ["Build three dashboards, one per metric", "Use a dashboard parameter bound to the query (or a field picker with the query returning multiple metric columns) so the visualization updates based on the selected metric", "Manually swap the chart's data source each time", "This isn't supported"], a: 1, e: "Parameterizing the query/visualization to accept a selected metric lets one dashboard serve multiple analytical views dynamically, avoiding the maintenance burden of near-duplicate dashboards for each metric.", t: "Scenario · Hard" },
    { q: "A monthly revenue query returns different totals each time an analyst reruns it during the day, confusing stakeholders, because upstream data is still loading incrementally throughout the day.", o: ["Assume the query is broken and rewrite it", "Communicate the data's incremental freshness explicitly (e.g., a 'last refreshed at' timestamp on the dashboard) and/or schedule the report after the known daily load window completes", "Cache the first result of the day permanently regardless of new data", "Disable the ability to rerun the query"], a: 1, e: "When upstream data loads incrementally, showing an explicit 'as of' / last-refreshed timestamp and aligning report schedules to after the load window are standard analyst practices to avoid confusing stakeholders with legitimately changing intraday numbers.", t: "Scenario · Medium" },
    { q: "A dashboard visual needs to show both an actual value and a target/goal line for context (e.g., actual sales vs. quota) in the same chart.", o: ["Only show the actual value with no reference", "Add a second series/reference line for the target value (from a goals table or hardcoded business target) alongside the actual measure in the same visualization", "Build two separate unrelated charts", "Replace the actual value with the target"], a: 1, e: "Combining an actual-value series with a target/reference line (sourced from a goals table or a fixed business target) in a single chart is standard practice for giving viewers immediate context on performance against expectations.", t: "Scenario · Medium" },
    { q: "A large query used in a dashboard runs fine in isolation but times out when many users load the dashboard simultaneously each morning.", o: ["Nothing can be done about concurrent load", "Increase the SQL warehouse's cluster count (multi-cluster / concurrency scaling) so it can serve more simultaneous queries, and/or leverage query result caching for identical repeated queries", "Ask users to stagger their logins manually", "Switch to a single, smaller warehouse"], a: 1, e: "Databricks SQL warehouses support scaling out (multiple clusters) to handle concurrent query load, and repeated identical queries can benefit from result caching — both directly address a dashboard becoming slow under simultaneous morning usage.", t: "Scenario · Medium" },
    { q: "An analyst building a funnel visualization (signup → activation → purchase) needs each stage's count to reflect only users who completed all prior stages, not independent counts per stage.", o: ["Count each stage independently with no relationship to prior stages", "Structure the query so each subsequent stage's count is filtered to the set of users who satisfied the previous stage's condition (a proper funnel/cohort definition)", "Show percentages with no underlying cohort logic", "Use a pie chart instead of a funnel"], a: 1, e: "A correct funnel requires cumulative, sequentially filtered cohorts — each stage's population must be a subset of the prior stage's — rather than independently counting users at each stage, which would misrepresent drop-off.", t: "Scenario · Medium" },
    { q: "A dashboard query joins a large fact table to a dimension table using a text-based key (e.g., customer email) and performance is noticeably worse than similar joins using integer keys elsewhere.", o: ["Text-based join keys perform identically to integer keys always", "Where feasible, use a surrogate integer key for the join (maintained via the data model) instead of a wide text key, since integer comparisons are generally faster and more compact than string comparisons at scale", "Add more slicers to the dashboard", "Switch the join to a UNION instead"], a: 1, e: "Joining on a shorter, fixed-width integer surrogate key is typically more efficient than joining on a wide text key, since integer comparison and hashing are cheaper — a common data-modeling recommendation for BI performance.", t: "Scenario · Medium" },
    { q: "Stakeholders ask why a dashboard's 'total customers' metric on a summary page doesn't match the sum of the per-region breakdown shown on another page.", o: ["This is always a bug and can be ignored", "Check for a double-counting issue — e.g., a customer appearing in multiple regions in the detail view (COUNT vs COUNT DISTINCT) — or a differing filter/date context between the two pages, and align the definitions", "Just hide one of the two pages", "Randomly adjust one number to match the other"], a: 1, e: "Metric mismatches between a summary and a detail breakdown are usually explained by either double-counting (a customer counted in multiple regions without COUNT DISTINCT) or inconsistent filter contexts between pages — the fix is to align the metric definitions and filters, not to paper over the discrepancy.", t: "Scenario · Hard" },
    { q: "A dashboard needs to compare performance across product categories that have very different scales (e.g., one category does $10M and another $10K), and a single bar chart makes the smaller category invisible.", o: ["Force both onto the same linear axis regardless of scale", "Consider a logarithmic scale, indexed/normalized values (e.g., % change from baseline), or small multiples so each category's trend is visible despite scale differences", "Remove the smaller category from the dashboard", "Show only the top category"], a: 1, e: "When absolute scales differ dramatically, a log scale, normalized/indexed metrics, or small-multiple layouts (separate panels per category) let viewers compare trends and performance meaningfully instead of one series flattening the other on a shared linear axis.", t: "Scenario · Hard" },
    { q: "An analyst must build a report showing rolling 7-day average revenue to smooth out day-of-week seasonality, refreshed daily.", o: ["Show raw daily revenue only", "Use a window function computing AVG(revenue) OVER a 7-day rolling window ordered by date, refreshed as part of the scheduled query", "Manually average the numbers in a spreadsheet each day", "Switch to monthly granularity instead"], a: 1, e: "A window function computing a moving average over a trailing N-day window ordered by date is the standard SQL technique for smoothing day-of-week seasonality into a rolling trend line, and it can run as part of a normally scheduled query refresh.", t: "Scenario · Hard" },
    { q: "A dashboard's query is correct but its result table is hard for non-technical stakeholders to scan quickly because it has 15 columns of raw detail.", o: ["Leave all 15 columns since more data is always better", "Redesign the visualization to surface only the handful of columns/metrics decision-makers actually need, moving detailed columns to a drill-through or a separate detailed view", "Convert the table into a word cloud", "Remove the table entirely with no replacement"], a: 1, e: "Good analyst practice is to design the primary view around the few metrics that matter to the audience, pushing exhaustive detail to a secondary drill-through table — improving scannability without losing access to the underlying detail.", t: "Scenario · Hard" },
    { q: "A dashboard must show the same revenue metric broken down by both product and region simultaneously, and a simple bar chart can't cleanly show two dimensions at once.", o: ["Force everything into one dimension and ignore the second", "Use a matrix/pivot table, a stacked bar chart, or a heatmap to represent two dimensions (product and region) crossed with the revenue measure in a single, readable visual", "Build ten separate charts, one per region", "Only show the totals with no breakdown"], a: 1, e: "Visualizations designed for two crossed dimensions — a pivot/matrix table, a stacked/grouped bar chart, or a heatmap — let viewers see a measure broken down by two dimensions at once far more cleanly than forcing a single-dimension chart type or fragmenting into many separate charts.", t: "Scenario · Medium" },
  ],
  "databricks-genai-engineer-associate": [
    { q: "A RAG chatbot gives confidently wrong answers when the retrieved context doesn't actually contain the answer to the user's question. What is the most direct mitigation at the retrieval/prompting layer?", o: ["Increase the LLM's temperature", "Improve retrieval quality (better chunking/embeddings, higher top-k or reranking) and instruct the prompt to answer only from context / say 'I don't know' when context is insufficient", "Remove the system prompt entirely", "Switch to a smaller embedding model"], a: 1, e: "Hallucination in RAG often stems from poor retrieval (irrelevant chunks) combined with a prompt that doesn't constrain the model to grounded answers. Improving retrieval and explicitly instructing the model to defer when context is insufficient are the standard first fixes.", t: "Scenario · Medium" },
    { q: "Long PDF documents are being chunked at a fixed 200-character size, causing many chunks to cut sentences and tables mid-way, hurting retrieval relevance.", o: ["Chunk size doesn't affect retrieval quality", "Use a larger, more context-aware chunking strategy (e.g., recursive/semantic chunking that respects sentence/section boundaries) with some overlap", "Skip chunking and embed the full document as one vector", "Convert PDFs to images instead"], a: 1, e: "Naive fixed-size chunking that ignores document structure fragments meaning across chunk boundaries. Semantic or structure-aware chunking (respecting paragraphs/sections) with slight overlap preserves context and improves retrieval relevance.", t: "Scenario · Medium" },
    { q: "A vector search index needs to return the most semantically similar documents to a user query embedding as fast as possible at scale, rather than an exact brute-force comparison.", o: ["A full linear scan comparing the query to every vector every time", "An approximate nearest neighbor (ANN) index (e.g., HNSW) that trades a small amount of recall for large speed gains at scale", "Sorting documents alphabetically", "Using SQL LIKE on the raw text"], a: 1, e: "Approximate nearest neighbor algorithms like HNSW are purpose-built for fast similarity search at scale, avoiding the cost of comparing a query embedding against every vector (brute-force), at the cost of a small, tunable amount of recall.", t: "Scenario · Medium" },
    { q: "A team must evaluate whether a new RAG pipeline retrieves relevant context for a benchmark set of questions, before evaluating the final generated answer quality.", o: ["Skip retrieval evaluation and only judge final answers", "Measure retrieval metrics such as precision/recall@k or whether ground-truth-relevant chunks appear in the top-k retrieved results", "Only use human vibes-based review", "Only test the LLM prompt in isolation"], a: 1, e: "Isolating retrieval evaluation (e.g., precision/recall@k against known relevant passages) is a standard step before end-to-end generation evaluation, since a good LLM cannot compensate for the wrong context ever being retrieved.", t: "Scenario · Medium" },
    { q: "An application must serve an LLM endpoint that stays warm with low first-token latency but should also scale down during off-hours to control cost.", o: ["A fixed, always-on cluster with no scaling", "Databricks Model Serving with a provisioned/scale-to-zero-aware endpoint configuration matched to traffic patterns", "Only batch inference jobs", "A local notebook execution only"], a: 1, e: "Databricks Model Serving endpoints support scaling configurations that balance latency and cost; choosing an appropriate concurrency/scaling setup (rather than a fixed always-on or purely batch approach) is the standard way to meet both latency and cost goals.", t: "Scenario · Medium" },
    { q: "Two different embedding models are candidates for a RAG system, and the team needs a rigorous way to choose. What should NOT be assumed?", o: ["Test both on the actual downstream retrieval task with representative queries", "That a higher-dimensional embedding model is automatically better for this specific domain and query style", "Compare cost and latency alongside quality", "Consider whether the embedding model was trained on similar domain text"], a: 1, e: "Higher embedding dimensionality doesn't guarantee better retrieval quality for a specific domain/task — it can even hurt cost/latency without benefit. The correct approach is empirical evaluation on representative queries plus considering cost, latency, and domain fit.", t: "Scenario · Hard" },
    { q: "A RAG system occasionally leaks a snippet of one customer's confidential document into another customer's chatbot answer because both are stored in the same vector index.", o: ["This is expected behavior for vector search", "Implement metadata-based access control/filtering (e.g., tenant_id filters) at query time so retrieval is scoped to the requesting customer's authorized documents only", "Delete the vector index entirely", "Only use one shared document set for all customers"], a: 1, e: "Multi-tenant RAG requires enforcing access control at retrieval time — typically via metadata filters (e.g., tenant/customer ID) applied to every vector search query — so cross-tenant leakage can't happen regardless of embedding similarity.", t: "Scenario · Hard" },
    { q: "An LLM-powered support agent needs to call an internal order-status API and return a natural-language answer using the live result, not a hallucinated guess.", o: ["Fine-tune the model on old order data instead", "Use function/tool calling: define the API as a callable tool the model can invoke, then feed the tool's real response back into the model to compose the final answer", "Ask the user to check the API themselves", "Embed the entire order database into the prompt"], a: 1, e: "Tool/function calling lets the LLM request a defined action (like an API call), have that real result returned to it, and then generate a grounded answer from actual live data — rather than relying on stale training data or hallucination.", t: "Scenario · Hard" },
    { q: "A team fine-tuned an open model on internal support tickets, but production answers now sound right but frequently cite made-up policy numbers not in the source data. What best explains this and the fix?", o: ["Fine-tuning eliminates all hallucination automatically", "Fine-tuning shapes style/format but doesn't guarantee factual grounding; pairing the fine-tuned model with retrieval (RAG) over verified policy documents keeps factual claims grounded in real sources", "Increase the model's temperature to reduce hallucination", "This means fine-tuning failed and should be abandoned entirely"], a: 1, e: "Fine-tuning primarily adjusts tone, format, and task style — it does not give the model reliable access to facts it wasn't trained to memorize, and can even increase confident fabrication. Combining it with RAG for factual grounding addresses the specific failure of invented details.", t: "Scenario · Hard" },
    { q: "A production GenAI application must log every prompt, retrieved context, and model response for compliance auditing and later quality review.", o: ["Rely on the LLM provider's own logs only", "Use MLflow tracing/logging (or an equivalent GenAI observability layer) to capture prompts, retrieved chunks, responses, and metadata for every request", "Sample 1 in 1000 requests manually", "Skip logging to save storage"], a: 1, e: "MLflow's tracing capabilities (and similar observability tooling) are designed to capture the full input/output/context chain of GenAI requests, which is the standard mechanism for compliance auditing and systematic quality review of a RAG or agent system in production.", t: "Scenario · Hard" },
    { q: "A RAG chatbot's answers are grounded correctly but users complain responses feel generic and don't reflect the company's tone/brand voice.", o: ["Retrieval quality is the only lever available", "Adjust the system prompt to specify tone/voice guidelines, and consider light fine-tuning or few-shot examples for style, since retrieval controls factual grounding while prompting/fine-tuning controls tone and style", "Switch to a larger base model only, with no prompt changes", "Remove the system prompt entirely"], a: 1, e: "Factual grounding (via retrieval) and stylistic tone are largely separate concerns: tone is best controlled through system-prompt instructions, few-shot style examples, or light fine-tuning, not by changing the retrieval pipeline.", t: "Scenario · Medium" },
    { q: "A team needs to choose an appropriate top-k value for retrieval in a RAG system, but setting k too high pushes irrelevant chunks into the prompt while k too low sometimes misses the needed context.", o: ["Always set k as high as possible for safety", "Tune k empirically against a labeled evaluation set (measuring answer quality and retrieval precision/recall) and consider reranking the top candidates to push the most relevant chunks first", "Always use k=1 regardless of task", "k has no measurable effect on output quality"], a: 1, e: "Top-k is a tunable hyperparameter best set through empirical evaluation on representative queries; adding a reranking step after initial retrieval lets you keep k reasonably small while ensuring the most relevant chunks are prioritized in the final context.", t: "Scenario · Medium" },
    { q: "An application embeds user documents once at upload time, but the embedding model is later upgraded to a better version, leaving the vector index inconsistent (mixed old/new embeddings).", o: ["Mixing embedding versions in one index has no consequence", "Re-embed all existing documents with the new model and rebuild the vector index, since embeddings from different models/versions aren't directly comparable in similarity search", "Only re-embed new documents going forward", "Average the old and new embedding vectors together"], a: 1, e: "Embeddings from different models (or versions) live in different vector spaces and generally aren't comparable; mixing them in one index corrupts similarity search. A full re-embed and index rebuild is required when upgrading the embedding model.", t: "Scenario · Medium" },
    { q: "A cost-sensitive GenAI application wants to reduce LLM API spend without materially hurting answer quality for a high-volume support use case.", o: ["Always use the largest, most expensive model for every request", "Consider request-appropriate model routing (a smaller/cheaper model for simple queries, a larger one for complex ones), prompt/context trimming, and caching repeated/common queries", "Increase max_tokens on every call to be safe", "Remove all guardrails to speed up responses"], a: 1, e: "Cost optimization for LLM applications typically combines model routing by query complexity, trimming unnecessary context/tokens, and caching frequent queries — rather than uniformly using the most expensive model for every request regardless of need.", t: "Scenario · Medium" },
    { q: "A GenAI application must prevent a user from manipulating the system prompt via crafted input (a prompt injection attempt) to bypass content restrictions.", o: ["Prompt injection cannot be mitigated at all", "Apply defenses such as input/output guardrails, clearly delimiting user content from instructions, and validating/filtering model outputs, while treating full prevention as an ongoing risk-reduction effort rather than a solved problem", "Trust that the base model always resists all injected instructions", "Remove the system prompt so there's nothing to bypass"], a: 1, e: "Prompt injection is a known, only partially mitigable risk; standard defenses include clear delimiting of untrusted user content from system instructions, input/output guardrails, and output validation — treating it as ongoing risk reduction rather than a fully solved problem.", t: "Scenario · Hard" },
    { q: "A RAG pipeline over PDF technical manuals with many tables performs poorly whenever answers require reading data out of a table, even though prose-based questions work well.", o: ["Tables are inherently impossible for RAG to handle", "Use a table-aware extraction/chunking approach (e.g., preserving table structure as markdown or structured text during ingestion) so table content is represented in a retrievable, LLM-readable form rather than being flattened or lost", "Remove all tables from the source documents", "Increase the LLM's context window only"], a: 1, e: "Naive PDF-to-text extraction often mangles tabular structure; explicitly extracting tables into a structured, LLM-friendly representation (e.g., markdown tables) during ingestion preserves the information needed to correctly answer table-based questions.", t: "Scenario · Hard" },
    { q: "An evaluation framework for a RAG system needs an automated, scalable way to judge answer quality against ground truth without a human reviewing every single response.", o: ["Only fully manual human review is possible", "Use an LLM-as-a-judge approach (a separate model scoring generated answers against reference answers/criteria) alongside a smaller human-reviewed sample for calibration", "Skip evaluation and trust user feedback alone", "Measure only latency, ignoring answer quality"], a: 1, e: "LLM-as-a-judge (using a capable model to score outputs against reference answers or rubrics) is a common scalable evaluation technique, typically calibrated and spot-checked against a smaller human-labeled sample to validate the judge's reliability.", t: "Scenario · Hard" },
    { q: "A GenAI feature must degrade gracefully — returning a helpful fallback response — when the underlying LLM API call times out or errors, rather than surfacing a raw error to the end user.", o: ["Let the raw exception propagate to the user interface", "Implement error handling with a graceful fallback (a friendly message, a retry with backoff, or a cached/simpler response) around the LLM call so failures don't break the user experience", "Remove error handling to keep the code simple", "Silently return an empty string with no explanation"], a: 1, e: "Production GenAI applications need explicit error handling around LLM calls — retries with backoff and a graceful, user-friendly fallback — so that transient API failures don't surface as raw errors or broken experiences to end users.", t: "Scenario · Hard" },
    { q: "A multi-turn conversational agent must decide when to summarize/compress older conversation turns to stay within the model's context window while a long support conversation continues.", o: ["Simply drop the oldest turns with no regard for content", "Implement a rolling summarization strategy that compresses older turns into a concise summary preserving key facts, appended before recent raw turns, keeping the prompt within budget while retaining important context", "Increase the context window as the only fix regardless of cost", "End the conversation once the window is full"], a: 1, e: "Rolling summarization — compressing older turns into a compact summary of key facts while keeping recent turns verbatim — is the standard technique for managing long conversations within a fixed context budget without abruptly losing important earlier information.", t: "Scenario · Hard" },
    { q: "A RAG agent's citations sometimes reference a document chunk that, on inspection, doesn't actually support the specific claim the model attributed to it.", o: ["Citations are always accurate if retrieval succeeded", "Add a grounding-verification step (or stricter prompting requiring the model to quote the exact supporting span) that checks generated claims against the actual retrieved text before returning the answer", "Remove citations entirely to avoid the issue", "Trust the model's citation without any verification"], a: 1, e: "Retrieval succeeding doesn't guarantee the model's generated claim is faithfully grounded in the cited chunk; adding a verification step (or requiring quoted spans) that checks claims against retrieved text catches this mismatch before the answer reaches the user.", t: "Scenario · Hard" },
  ],
};
